/// A task in a list or detail.
class TaskItem {
  /// Block ID (`t-…`).
  final String id;

  /// The note holding the line.
  final String noteId;

  /// That note's title.
  final String noteTitle;

  /// Description (no emoji fields).
  final String description;

  /// State.
  final TaskState state;

  /// Priority (`highest` … `lowest`, `normal`).
  final String priority;

  /// 📅 due.
  final DateTime? due;

  /// ⏳ scheduled.
  final DateTime? scheduled;

  /// ✅ done date.
  final DateTime? done;

  /// Recurrence phrase as written (`every month on the 1st`).
  final String? recurrence;

  /// `false` when the phrase is outside the grammar ("recurrence not understood").
  final bool recurrenceUnderstood;

  /// Reminders.
  final List<ReminderItem> reminders;

  /// Linked notes/entities (wikilinks in the line).
  final List<EntityRef> links;

  /// Has unsynced changes.
  final bool pendingSync;

  const TaskItem({
    required this.id,
    required this.noteId,
    required this.noteTitle,
    required this.description,
    required this.state,
    required this.priority,
    this.due,
    this.scheduled,
    this.done,
    this.recurrence,
    required this.recurrenceUnderstood,
    required this.reminders,
    required this.links,
    required this.pendingSync,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      noteId.hashCode ^
      noteTitle.hashCode ^
      description.hashCode ^
      state.hashCode ^
      priority.hashCode ^
      due.hashCode ^
      scheduled.hashCode ^
      done.hashCode ^
      recurrence.hashCode ^
      recurrenceUnderstood.hashCode ^
      reminders.hashCode ^
      links.hashCode ^
      pendingSync.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TaskItem &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          noteId == other.noteId &&
          noteTitle == other.noteTitle &&
          description == other.description &&
          state == other.state &&
          priority == other.priority &&
          due == other.due &&
          scheduled == other.scheduled &&
          done == other.done &&
          recurrence == other.recurrence &&
          recurrenceUnderstood == other.recurrenceUnderstood &&
          reminders == other.reminders &&
          links == other.links &&
          pendingSync == other.pendingSync;
}

/// Field edits of a task: `None` leaves a field unchanged; the `clear_*` flags remove it.
class TaskPatch {
  /// New description.
  final String? text;

  /// New 📅.
  final DateTime? due;

  /// Remove 📅.
  final bool clearDue;

  /// New 🔁 phrase.
  final String? recurrence;

  /// Remove 🔁.
  final bool clearRecurrence;

  /// Replace all reminders.
  final List<DateTime>? reminders;

  /// New priority (`normal` removes it).
  final String? priority;

  const TaskPatch({
    this.text,
    this.due,
    required this.clearDue,
    this.recurrence,
    required this.clearRecurrence,
    this.reminders,
    this.priority,
  });

  static Future<TaskPatch> default_() =>
      StrataCore.instance.api.crateViewModelTaskPatchDefault();

  @override
