      text.hashCode ^
      due.hashCode ^
      clearDue.hashCode ^
      recurrence.hashCode ^
      clearRecurrence.hashCode ^
      reminders.hashCode ^
      priority.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TaskPatch &&
          runtimeType == other.runtimeType &&
          text == other.text &&
          due == other.due &&
          clearDue == other.clearDue &&
          recurrence == other.recurrence &&
          clearRecurrence == other.clearRecurrence &&
          reminders == other.reminders &&
          priority == other.priority;
}

